#pragma once

#include <cstddef>
#include <cstdint>
#include <span>
#include <string_view>
#include <vector>

/// Unicode character properties and text segmentation (milestone 9 bis, part 4): what the text
/// layout needs to be right in every language, written in the engine from the Unicode Character
/// Database (tables generated by tools/text/make_unicode_tables.py, see unicode_version()).
///
/// - char_info(): the properties of a code point (bidirectional class, line breaking class, general
///   category, grapheme break, script).
/// - grapheme_boundaries(): the user-perceived characters (UAX #29): where a text cursor may stop,
///   what a fallback font must cover as a whole.
/// - line_breaks(): where a line may or must end (UAX #14, default rules).
///
/// Everything here is pure computation: callable from any thread, no allocation except the vectors
/// returned. The bidirectional algorithm is in bidi.hpp.
namespace moteur::unicode {

/// Bidi_Class (UAX #9). Same order as tools/text/make_unicode_tables.py.
enum class BidiClass : std::uint8_t {
    L, R, AL, EN, ES, ET, AN, CS, NSM, BN, B, S, WS, ON, LRE, LRO, RLE, RLO, PDF, LRI, RLI, FSI, PDI
};

/// Line_Break (UAX #14). Same order as tools/text/make_unicode_tables.py. IN_ is the class IN
/// (inseparable), renamed: the Windows headers define IN as a macro.
enum class LineBreakClass : std::uint8_t {
    XX, AI, AK, AL, AP, AS, B2, BA, BB, BK, CB, CJ, CL, CM, CP, CR, EB, EM, EX, GL, H2, H3, HH, HL, HY, ID,
    IN_, IS, JL, JT, JV, LF, NL, NS, NU, OP, PO, PR, QU, RI, SA, SG, SP, SY, VF, VI, WJ, ZW, ZWJ
};

/// General_Category. Same order as tools/text/make_unicode_tables.py (Cn, unassigned, is 0).
enum class GeneralCategory : std::uint8_t {
    Cn, Lu, Ll, Lt, Lm, Lo, Mn, Mc, Me, Nd, Nl, No, Pc, Pd, Ps, Pe, Pi, Pf, Po, Sm, Sc, Sk, So, Zs, Zl, Zp,
    Cc, Cf, Cs, Co
};

/// Grapheme_Cluster_Break (UAX #29). Same order as tools/text/make_unicode_tables.py.
enum class GraphemeBreak : std::uint8_t {
    Other, CR, LF, Control, Extend, ZWJ, RegionalIndicator, Prepend, SpacingMark, L, V, T, LV, LVT
};

/// Indic_Conjunct_Break (UAX #29, rule GB9c).
enum class ConjunctBreak : std::uint8_t { None, Linker, Consonant, Extend };

/// Script indices: char_info().script; script_tag() gives the ISO 15924 tag of the others.
///@{
constexpr std::uint8_t kScriptUnknown = 0;    ///< "Zzzz": unassigned code points
constexpr std::uint8_t kScriptCommon = 1;     ///< "Zyyy": punctuation, digits, symbols shared by scripts
constexpr std::uint8_t kScriptInherited = 2;  ///< "Zinh": combining marks taking their base's script
///@}

/// The properties of one code point.
struct CharInfo {
    BidiClass bidi = BidiClass::L;                    ///< Bidi_Class
    LineBreakClass line = LineBreakClass::XX;         ///< Line_Break (before the resolutions of rule LB1)
    GeneralCategory category = GeneralCategory::Cn;  ///< General_Category
    GraphemeBreak grapheme = GraphemeBreak::Other;   ///< Grapheme_Cluster_Break
    ConjunctBreak conjunct = ConjunctBreak::None;    ///< Indic_Conjunct_Break
    bool east_asian = false;  ///< East_Asian_Width F, W or H (the "$EastAsian" set of UAX #14)
    bool extended_pictographic = false;  ///< Extended_Pictographic (emoji and the like)
    std::uint8_t script = kScriptUnknown;  ///< see script_tag()
};

/// The properties of `code_point`; a value beyond U+10FFFF gets those of an unassigned one. O(1).
CharInfo char_info(char32_t code_point);

/// The ISO 15924 tag of a script index ("Latn", "Arab", "Hani"...); "Zzzz" for an index out of
/// range. A static string.
const char* script_tag(std::uint8_t script);

/// The version of the Unicode Character Database the tables come from ("17.0.0").
const char* unicode_version();

/// The other bracket of a paired bracket (Bidi_Paired_Bracket): U+0028 gives U+0029 and the
/// reverse. `opening` (if not null) tells which side `code_point` is. 0 for a code point that is
/// not a paired bracket.
char32_t paired_bracket(char32_t code_point, bool* opening = nullptr);

/// The positions where a grapheme cluster (a user-perceived character: "e" + combining accent,
/// a flag, a family emoji, a Hangul syllable, a Devanagari conjunct) begins, plus the end of the
/// text: 0 first, `text.size()` last (just {0} for an empty text). Extended grapheme clusters of
/// UAX #29, without tailoring.
std::vector<std::size_t> grapheme_boundaries(std::u32string_view text);

/// What may happen between two characters (line_breaks()).
enum class LineBreak : std::uint8_t {
    None,       ///< the line must not end here
    Allowed,    ///< the line may end here (a break opportunity)
    Mandatory,  ///< the line must end here (after a newline, a paragraph separator...)
};

/// The line breaking opportunities of a text (UAX #14, the default rules, no tailoring): element i
/// says what may happen just before `text[i]`; there are `text.size() + 1` elements, the first one
/// None (never break at the start) and the last one Mandatory (always break at the end).
/// Characters of class SA (Thai, Lao, Khmer, Myanmar), which need a dictionary, are treated as
/// letters (AL) or marks: such text breaks only at spaces.
std::vector<LineBreak> line_breaks(std::u32string_view text);

}  // namespace moteur::unicode
